import argparse, csv, hashlib
from pathlib import Path

ap=argparse.ArgumentParser(); ap.add_argument("--phase3-dir",required=True); a=ap.parse_args()
p=Path(a.phase3_dir).expanduser().resolve(); report=p/"PHASE3_COMPLETION_REPORT.md"
if "test" in str(p).lower() or p.name!="Phase_3" or not p.is_dir(): raise ValueError("Refusing test path; use an existing Phase_3 directory")
if report.exists(): raise FileExistsError("Refusing to overwrite "+str(report))
def digest(x):
 h=hashlib.sha256()
 with x.open("rb") as f:
  for b in iter(lambda:f.read(1<<20),b""): h.update(b)
 return h.hexdigest()
def rows(x):
 if not x.is_file(): return []
 with x.open(encoding="utf-8-sig",newline="") as f: return list(csv.DictReader(f))
def files(pattern): return sorted(x for x in p.glob(pattern) if x.is_file() and "test" not in x.name.lower())
def choose(stem):
 v=p/(stem+"_v2.csv"); old=p/(stem+".csv"); return v if v.is_file() else old if old.is_file() else v
demo_p,voice_p,lat_p=choose("demo_log"),choose("voice_log"),choose("latency_log"); paths=[p,report,demo_p,voice_p,lat_p]
if any("test" in str(x).lower() for x in paths): raise ValueError("Refusing a path containing 'test'")
demo,voice,lat=rows(demo_p),rows(voice_p),rows(lat_p); conds={c:sum(str(r.get("condition (slow/fast/noisy)","")).strip().lower()==c for r in voice) for c in ("slow","fast","noisy")}; matches=sum(str(r.get("transcript_matches (Y/N)","")).strip().upper()=="Y" for r in voice); changed=sum(str(r.get("asr_changed_meaning (Y/N)","")).strip().upper()=="Y" for r in voice)
print("voice_runs",len(voice),"conditions",conds,"transcript_matches_Y",matches,"asr_meaning_changes_Y",changed); print("demo_rows",len(demo),"empty_actual_label",sum(not str(r.get("actual_label","")).strip() for r in demo))
if len(voice)<10: print("WARNING: fewer than 10 voice runs")
drop=files("p3_dropdown_*.png"); shots=files("p3_*.png"); case_shots=files("p3_five_cases_*.png"); voice_shots=files("p3_voice_run_*.png"); review_shots=files("p3_review_output_*.png"); fresh=files("phase3_fresh_runtime_check_*.log"); video=p/"p3_backup_demo.mp4"; screenshot_names=["p3_dropdown_01.png","p3_five_cases_01.png","p3_voice_run_01.png","p3_review_output_01.png"]
demo5=len(demo)==5 and len({str(r.get("case_id","")).strip() for r in demo})==5 and all(str(r.get("actual_label","")).strip() for r in demo); outputs=demo5 and all(all(str(r.get(k,"")).strip() for k in ("score_out_of_2","confidence","review_flag")) for r in demo)
voice10=len(voice)==10 and conds=={"slow":4,"fast":3,"noisy":3}; trans=voice10 and all(all(str(r.get(k,"")).strip() for k in ("transcript","transcript_matches (Y/N)","asr_changed_meaning (Y/N)")) for r in voice)
lat_ok=any(str(r.get("block","")).strip().lower() in ("block 62","62","cell 163") and str(r.get("run_label","")).strip().lower()=="batch-1" for r in lat) and any(str(r.get("block","")).strip().lower() in ("block 62","62","cell 163") and str(r.get("run_label","")).strip().lower()=="batch-15" for r in lat)
items=[("dropdown tested",(p/"p3_dropdown_01.png").is_file(),["p3_dropdown_01.png"],drop), ("five cases tested",demo5,["five unique demo rows in "+demo_p.name], [demo_p]+case_shots), ("voice test (10)",voice10,["10 rows (4 slow, 3 fast, 3 noisy) in "+voice_p.name],[voice_p]), ("transcription failures recorded",trans,["transcript and both ASR flags filled in "+voice_p.name],[voice_p]), ("score/confidence/review inspected",outputs,["five rows with actual_label, score_out_of_2, confidence, review_flag in "+demo_p.name],[demo_p]), ("fresh-runtime A_predict run",any(x.stat().st_size>0 for x in fresh),["phase3_fresh_runtime_check_*.log downloaded locally"],fresh), ("Block 62 latency",lat_ok,["Block 62 batch-1 and batch-15 rows in "+lat_p.name],[lat_p]), ("screenshots",all((p/n).is_file() for n in screenshot_names),screenshot_names,shots), ("backup video",video.is_file() and video.stat().st_size>0,["p3_backup_demo.mp4"],[video] if video.is_file() else [])]
lines=["# Phase 3 completion evidence check","","Generated by the local read-only checker. No answers are included.",""]
for name,ok,expected,found in items:
 missing=[e for e in expected if not (e in [x.name for x in found] or (e.startswith("phase3_fresh") and found) or (" in " in e and e.split(" in ",1)[1]==demo_p.name and demo_p.is_file()) or (" in " in e and e.split(" in ",1)[1]==voice_p.name and voice_p.is_file()) or (" in " in e and e.split(" in ",1)[1]==lat_p.name and lat_p.is_file()))]
 lines += [f"- {'DONE' if ok else 'MISSING'} — {name}"]
 if missing: lines.append("  - Expected file/evidence not found: "+"; ".join(missing)); print(name,"missing",*missing)
 elif not ok: lines.append("  - Required rows or fields are incomplete")
 for x in found: lines.append(f"  - {x.name} | SHA-256 {digest(x)}" if x.is_file() else f"  - {x.name} | missing")
with report.open("x",encoding="utf-8") as f: f.write("\n".join(lines)+"\n")
print("rows",len(demo),len(voice),len(lat),"report",report)
